temperatures = {
    "Monday": 72,
    "Tuesday": 68,
    "Wednesday": 75
}

print("Keys:")
for day in temperatures:
    print(day)

print("\nValues:")
for temp in temperatures.values():
    print(temp)

print("\nPairs:")
for day, temp in temperatures.items():
    print(day, temp)

profile = {
    "username": "pixelcat",
    "level": 7,
    "active": True
}

print("level" in profile)     # True
print("email" in profile)     # False

if "username" in profile:
    print(profile["username"])  # pixelcat

if "email" in profile:
    print(profile["email"])
else:
    print("No email saved")      # No email saved
